window.auroraShaderSources={vertex:"#version 300 es\n    in vec2 aPosition;\n\n    void main() {\n      gl_Position = vec4(aPosition, 0.0, 1.0);\n    }\n  ",fragment:"#version 300 es\n    precision highp float;\n\n    uniform float uTime;\n    uniform float uAmplitude;\n    uniform vec3 uColorStops[3];\n    uniform vec2 uResolution;\n    uniform float uBlend;\n    uniform float uTimeOffset;\n\n    out vec4 fragColor;\n\n    vec3 permute(vec3 x) {\n      return mod(((x * 34.0) + 1.0) * x, 289.0);\n    }\n\n    float snoise(vec2 v) {\n      const vec4 C = vec4(\n        0.211324865405187, 0.366025403784439,\n        -0.577350269189626, 0.024390243902439\n      );\n      vec2 i = floor(v + dot(v, C.yy));\n      vec2 x0 = v - i + dot(i, C.xx);\n      vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);\n      vec4 x12 = x0.xyxy + C.xxzz;\n      x12.xy -= i1;\n      i = mod(i, 289.0);\n\n      vec3 p = permute(\n        permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0)\n      );\n\n      vec3 m = max(\n        0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)),\n        0.0\n      );\n      m = m * m;\n      m = m * m;\n\n      vec3 x = 2.0 * fract(p * C.www) - 1.0;\n      vec3 h = abs(x) - 0.5;\n      vec3 ox = floor(x + 0.5);\n      vec3 a0 = x - ox;\n      m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);\n\n      vec3 g;\n      g.x = a0.x * x0.x + h.x * x0.y;\n      g.yz = a0.yz * x12.xz + h.yz * x12.yw;\n      return 130.0 * dot(m, g);\n    }\n\n    vec3 colorRamp(float factor) {\n      vec3 color = mix(uColorStops[0], uColorStops[1], smoothstep(0.0, 0.5, factor));\n      return mix(color, uColorStops[2], smoothstep(0.5, 1.0, factor));\n    }\n\n    void main() {\n      float time = uTime + uTimeOffset;\n      vec2 uv = gl_FragCoord.xy / uResolution;\n      vec3 rampColor = colorRamp(uv.x);\n\n      float height = snoise(vec2(uv.x * 2.0 + time * 0.1, time * 0.25)) * 0.5 * uAmplitude;\n      height = exp(height);\n      height = uv.y * 2.0 - height + 0.2;\n\n      float intensity = 0.6 * height;\n      float midPoint = 0.2;\n      float auroraAlpha = smoothstep(midPoint - uBlend * 0.5, midPoint + uBlend * 0.5, intensity);\n      vec3 auroraColor = intensity * rampColor;\n\n      fragColor = vec4(auroraColor * auroraAlpha, auroraAlpha);\n    }\n  "};